def transform(grid):
    out = [row[:] for row in grid]
    n, m = len(grid), len(grid[0])
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 3:
                out[r][c] = grid[n - 1 - r][m - 1 - c]
    return out
